import re
t = FILE_CONTENT
lines = t.split('\n')
print("lines:", len(lines), "chars:", len(t))
print("em dashes:", t.count('—'), "en dashes:", t.count('–'))
for i,l in enumerate(lines,1):
    if '—' in l or '–' in l: print("DASH", i, l[:90])
for kw in ['surger','Tezino','injur','DEXA','DXA','medical','health']:
    hits=[(i,l[:110]) for i,l in enumerate(lines,1) if kw.lower() in l.lower()]
    print(f"\n[{kw}] {len(hits)} hits")
    for h in hits: print("  ", h[0], h[1])
print("\nsections:", [l for l in lines if l.startswith('## ')])

